import React, {
  useRef,
  useState,
  useEffect,
  type CSSProperties,
  type ReactNode,
} from 'react';
import type {
  Theme,
  FadeProps,
  SecHeadProps,
  ChipProps,
  TagProps,
  BarProps,
} from '../types';

// ─── useInView hook ────────────────────────────────────────
export function useInView(
  threshold = 0.15,
): [React.RefObject<HTMLDivElement>, boolean] {
  const ref = useRef<HTMLDivElement>(null);
  const [visible, setVisible] = useState(false);

  useEffect(() => {
    const el = ref.current;
    if (!el) return;
    const obs = new IntersectionObserver(
      ([entry]) => {
        if (entry.isIntersecting) {
          setVisible(true);
          obs.disconnect();
        }
      },
      { threshold },
    );
    obs.observe(el);
    return () => obs.disconnect();
  }, [threshold]);

  return [ref, visible];
}

// ─── Fade-in wrapper ──────────────────────────────────────
export function Fade({ children, style, delay = 0 }: FadeProps) {
  const [ref, visible] = useInView();
  return (
    <div
      ref={ref}
      style={{
        opacity: visible ? 1 : 0,
        transform: visible ? 'none' : 'translateY(28px)',
        transition: `opacity 0.7s ease ${delay}s, transform 0.7s ease ${delay}s`,
        ...style,
      }}
    >
      {children}
    </div>
  );
}

// ─── Hero entrance (no scroll trigger needed) ─────────────
export function HeroFade({
  children,
  delay,
  style,
  className,
}: {
  children: ReactNode;
  delay: number;
  style?: CSSProperties;
  className?: string;
}) {
  const [show, setShow] = useState(false);
  useEffect(() => {
    const id = setTimeout(() => setShow(true), 80);
    return () => clearTimeout(id);
  }, []);

  return (
    <div
      className={className}
      style={{
        opacity: show ? 1 : 0,
        transform: show ? 'none' : 'translateY(24px)',
        transition: `opacity 0.7s ease ${delay}s, transform 0.7s ease ${delay}s`,
        ...style,
      }}
    >
      {children}
    </div>
  );
}

// ─── Section header ───────────────────────────────────────
export function SectionHeader({ num, title, t }: SecHeadProps) {
  return (
    <div
      style={{
        display: 'flex',
        alignItems: 'baseline',
        gap: 20,
        marginBottom: 52,
      }}
    >
      <span
        style={{
          fontSize: 11,
          letterSpacing: '0.1em',
          color: t.text3,
          fontFamily: 'DM Mono, monospace',
        }}
      >
        {num}
      </span>
      <h2
        style={{
          fontFamily: 'Syne, sans-serif',
          fontSize: 36,
          fontWeight: 700,
          letterSpacing: '-0.03em',
          color: t.text,
          margin: 0,
        }}
      >
        {title}
      </h2>
      <div
        style={{ flex: 1, height: 1, background: t.border, marginLeft: 12 }}
      />
    </div>
  );
}

// ─── Chip ─────────────────────────────────────────────────
export function Chip({ label, t }: ChipProps) {
  return (
    <span
      style={{
        fontSize: 11,
        padding: '5px 12px',
        borderRadius: 3,
        background: t.chipBg,
        border: `1px solid ${t.chipBorder}`,
        color: t.text2,
        letterSpacing: '0.02em',
        whiteSpace: 'nowrap',
      }}
    >
      {label}
    </span>
  );
}

// ─── Tag ──────────────────────────────────────────────────
export function Tag({ label, accent, t }: TagProps) {
  const color = t[accent] as string;
  const dim = t[`${accent}Dim` as keyof Theme] as string;
  return (
    <span
      style={{
        fontSize: 10,
        padding: '3px 10px',
        borderRadius: 2,
        background: dim,
        color,
        border: `1px solid ${color}33`,
        letterSpacing: '0.06em',
        textTransform: 'uppercase',
      }}
    >
      {label}
    </span>
  );
}

// ─── Skill bar ────────────────────────────────────────────
export function SkillBar({ skill, idx, visible, t }: BarProps) {
  const color = t[skill.color] as string;
  return (
    <div
      style={{
        opacity: visible ? 1 : 0,
        transform: visible ? 'none' : 'translateY(20px)',
        transition: `opacity 0.5s ease ${idx * 0.07}s, transform 0.5s ease ${idx * 0.07}s`,
      }}
    >
      <div
        style={{
          display: 'flex',
          justifyContent: 'space-between',
          marginBottom: 8,
        }}
      >
        <span style={{ fontSize: 12, color: t.text2, letterSpacing: '0.04em' }}>
          {skill.name}
        </span>
        <span
          style={{
            fontSize: 11,
            color: t.text3,
            fontVariantNumeric: 'tabular-nums',
          }}
        >
          {skill.pct}%
        </span>
      </div>
      <div
        style={{
          height: 2,
          background: 'rgba(128,128,128,0.1)',
          borderRadius: 2,
          position: 'relative',
        }}
      >
        <div
          style={{
            height: '100%',
            borderRadius: 2,
            background: color,
            width: visible ? `${skill.pct}%` : '0%',
            transition: `width 1.2s cubic-bezier(0.16,1,0.3,1) ${idx * 0.08 + 0.1}s`,
            position: 'relative',
          }}
        >
          <div
            style={{
              position: 'absolute',
              right: -4,
              top: -4,
              width: 10,
              height: 10,
              borderRadius: '50%',
              background: color,
              boxShadow: `0 0 10px ${color}`,
            }}
          />
        </div>
      </div>
    </div>
  );
}
