// ─── Stack ────────────────────────────────────────────────
export function StackSection({ t }: ThemeProps) {
  return (
    <section
      id='stack'
      style={{ borderTop: `1px solid ${t.border}`, background: t.bg }}
    >
      <div
        className='cv-inner'
        style={{ padding: '100px clamp(20px, 5vw, 48px)' }}
      >
        <SectionHeader num='01' title='Tech stack' t={t} />
        <div style={{ display: 'flex', flexDirection: 'column', gap: 2 }}>
          {STACK.map((layer, i) => {
            const color = accent(t, layer.accent);
            return (
              <Fade key={layer.label} delay={i * 0.08}>
                <div
                  className='stack-row'
                  style={{
                    display: 'grid',
                    gridTemplateColumns: '120px 1fr',
                    alignItems: 'center',
                    gap: 32,
                    padding: '20px 28px',
                    borderRadius: 6,
                    background: `${color}12`,
                    border: `1px solid ${color}33`,
                    transition: 'transform 0.25s ease',
                    cursor: 'default',
                  }}
                  onMouseEnter={(e) =>
                    ((e.currentTarget as HTMLDivElement).style.transform =
                      'translateX(8px)')
                  }
                  onMouseLeave={(e) =>
                    ((e.currentTarget as HTMLDivElement).style.transform =
                      'none')
                  }
                >
                  <div>
                    <div
                      style={{
                        fontSize: 10,
                        letterSpacing: '0.14em',
                        textTransform: 'uppercase',
                        fontWeight: 500,
                        color,
                        marginBottom: 4,
                      }}
                    >
                      {layer.label}
                    </div>
                    <div
                      style={{
                        fontSize: 9,
                        letterSpacing: '0.08em',
                        color: t.text3,
                      }}
                    >
                      {layer.depth}
                    </div>
                  </div>
                  <div style={{ display: 'flex', gap: 8, flexWrap: 'wrap' }}>
                    {layer.chips.map((c) => (
                      <Chip key={c} label={c} t={t} />
                    ))}
                  </div>
                </div>
              </Fade>
            );
          })}
        </div>
      </div>
    </section>
  );
}

// ─── Skills ───────────────────────────────────────────────
export function SkillsSection({ t }: ThemeProps) {
  const [ref, visible] = useInView();
  return (
    <section
      id='skills'
      style={{ borderTop: `1px solid ${t.border}`, background: t.surface }}
    >
      <div
        ref={ref}
        className='cv-inner'
        style={{ padding: '100px clamp(20px, 5vw, 48px)' }}
      >
        <SectionHeader num='02' title='Proficiency' t={t} />
        <div
          className='skills-grid'
          style={{
            display: 'grid',
            gridTemplateColumns: '1fr 1fr',
            gap: '28px 64px',
          }}
        >
          {SKILLS.map((s, i) => (
            <SkillBar key={s.name} skill={s} idx={i} visible={visible} t={t} />
          ))}
        </div>
      </div>
    </section>
  );
}

// ─── Experience ───────────────────────────────────────────
export function ExperienceSection({ t }: ThemeProps) {
  return (
    <section
      id='experience'
      style={{ borderTop: `1px solid ${t.border}`, background: t.bg }}
    >
      <div
        className='cv-inner'
        style={{ padding: '100px clamp(20px, 5vw, 48px)' }}
      >
        <SectionHeader num='03' title='Experience' t={t} />
        <div style={{ position: 'relative', paddingLeft: 32 }}>
          <div
            style={{
              position: 'absolute',
              left: 5,
              top: 8,
              bottom: 0,
              width: 1,
              background: `linear-gradient(to bottom, ${t.purple}, transparent)`,
            }}
          />
          {EXPERIENCE.map((exp, i) => {
            const color = accent(t, exp.accent);
            return (
              <Fade
                key={exp.role}
                delay={i * 0.12}
                style={{ paddingBottom: i < EXPERIENCE.length - 1 ? 56 : 0 }}
              >
                <div style={{ position: 'relative' }}>
                  <div
                    style={{
                      position: 'absolute',
                      left: -31,
                      top: 6,
                      width: 10,
                      height: 10,
                      borderRadius: '50%',
                      border: `2px solid ${color}`,
                      background: t.bg,
                    }}
                  />
                  <div
                    style={{
                      fontFamily: 'Syne, sans-serif',
                      fontSize: 20,
                      fontWeight: 600,
                      color: t.text,
                      letterSpacing: '-0.02em',
                      marginBottom: 4,
                    }}
                  >
                    {exp.role}
                  </div>
                  <div
                    style={{
                      fontSize: 12,
                      color: t.purple,
                      letterSpacing: '0.04em',
                      marginBottom: 2,
                    }}
                  >
                    {exp.company}
                  </div>
                  <div
                    style={{
                      fontSize: 11,
                      color: t.text3,
                      letterSpacing: '0.06em',
                      marginBottom: 12,
                    }}
                  >
                    {exp.date}
                  </div>
                  <p
                    style={{
                      fontSize: 13,
                      color: t.text2,
                      lineHeight: 1.7,
                      maxWidth: 560,
                      marginBottom: 14,
                      fontFamily: 'DM Mono, monospace',
                    }}
                  >
                    {exp.desc}
                  </p>
                  <div style={{ display: 'flex', gap: 8, flexWrap: 'wrap' }}>
                    {exp.tags.map(([tag, a]) => (
                      <Tag key={tag} label={tag} accent={a} t={t} />
                    ))}
                  </div>
                </div>
              </Fade>
            );
          })}
        </div>
      </div>
    </section>
  );
}

