import React from 'react';
import { Helmet } from 'react-helmet';
import type { Theme } from '../types';
import { DARK, LIGHT } from '../data';
import { themeRef } from '../components/scene';
import { usePersistentTheme } from '../hooks/usePersistentTheme';
import { useVisitCounter } from '../hooks/useVisitCounter';
import { Layout } from '../components/Layout';
import {
  Hero,
  StackSection,
  SkillsSection,
  ExperienceSection,
  ProjectsSection,
  ContactSection,
} from '../components/sections';

// ThreeCanvas is only safe in the browser (no SSR / window)
// Gatsby's loadable with { ssr: false } pattern is the cleanest approach
import loadable from '@loadable/component';
const ThreeCanvas = loadable(
  () =>
    import('../components/scene').then((mod) => ({ default: mod.ThreeCanvas })),
  { ssr: false },
);

// ─── Page ─────────────────────────────────────────────────
export default function IndexPage() {
  const [isLight, toggle] = usePersistentTheme();
  useVisitCounter();
  const t: Theme = isLight ? LIGHT : DARK;

  // Sync theme to the mutable ref so R3F reads it every frame
  themeRef.current = t;

  return (
    <>
      <Helmet>
        <html lang='en' />
        <title>Sanjeera Di · Full Stack Developer</title>
        <link rel='icon' href='/favicon.ico' />
        <link rel='shortcut icon' href='/favicon.ico' />
        <meta
          name='description'
          content='Multi-disciplinary Full Stack Developer building scalable, cloud-native solutions. 10+ years in React, Vue, Node.js, NestJS, AWS and Azure.'
        />
        <meta name='viewport' content='width=device-width, initial-scale=1' />
        <meta
          property='og:title'
          content='Sanjeera Di · Full Stack Developer'
        />
        <meta
          property='og:description'
          content='Portfolio of Sanjeera Di — Full Stack Developer, Melbourne AU.'
        />
        <meta property='og:type' content='website' />
      </Helmet>

      <Layout
        t={t}
        isLight={isLight}
        toggle={toggle}
        background={<ThreeCanvas />}
      >
        <Hero t={t} />
        <StackSection t={t} />
        <SkillsSection t={t} />
        <ExperienceSection t={t} />
        <ProjectsSection t={t} />
        <ContactSection t={t} />
      </Layout>
    </>
  );
}
