import React from 'react';
import { Link } from 'gatsby';
import type { Theme, Project } from '../types';

export function ProjectCard({ project, t }: { project: Project; t: Theme }) {
  const color = t[project.accent] as string;

  return (
    <Link
      to={`/projects/?project=${encodeURIComponent(project.slug)}`}
      style={{
        background: t.bg,
        border: `1px solid ${t.border}`,
        borderRadius: 8,
        padding: 28,
        transition: 'border-color 0.25s, transform 0.25s',
        cursor: 'pointer',
        height: '100%',
        textDecoration: 'none',
        display: 'block',
      }}
      onMouseEnter={(e) => {
        const el = e.currentTarget as HTMLAnchorElement;
        el.style.borderColor = `${color}66`;
        el.style.transform = 'translateY(-4px)';
      }}
      onMouseLeave={(e) => {
        const el = e.currentTarget as HTMLAnchorElement;
        el.style.borderColor = t.border;
        el.style.transform = 'none';
      }}
    >
      <div
        style={{
          display: 'flex',
          justifyContent: 'space-between',
          marginBottom: 14,
        }}
      >
        <div
          style={{
            width: 36,
            height: 36,
            borderRadius: 6,
            background: `${color}22`,
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
          }}
        >
          <svg
            width='16'
            height='16'
            viewBox='0 0 24 24'
            fill='none'
            stroke={color}
            strokeWidth='1.5'
          >
            <circle cx='12' cy='12' r='3' />
            <path d='M12 2v3M12 19v3M4.22 4.22l2.12 2.12M17.66 17.66l2.12 2.12M2 12h3M19 12h3' />
          </svg>
        </div>
        <span
          style={{
            fontSize: 10,
            letterSpacing: '0.1em',
            textTransform: 'uppercase',
            color: t.text3,
            textDecoration: 'none',
          }}
        >
          view details -&gt;
        </span>
      </div>

      <div
        style={{
          fontFamily: 'Syne, sans-serif',
          fontSize: 18,
          fontWeight: 600,
          color: t.text,
          letterSpacing: '-0.02em',
          marginBottom: 8,
        }}
      >
        {project.name}
      </div>

      <p
        style={{
          fontSize: 12,
          color: t.text2,
          lineHeight: 1.6,
          marginBottom: 16,
          fontFamily: 'DM Mono, monospace',
        }}
      >
        {project.desc}
      </p>

      <div style={{ display: 'flex', gap: 6, flexWrap: 'wrap' }}>
        {project.chips.map((c) => (
          <span
            key={c}
            style={{
              fontSize: 10,
              padding: '3px 8px',
              borderRadius: 2,
              background: t.chipBg,
              border: `1px solid ${t.border}`,
              color: t.text3,
              letterSpacing: '0.04em',
            }}
          >
            {c}
          </span>
        ))}
      </div>
    </Link>
  );
}
