import { useEffect } from 'react';

const VISIT_ENDPOINT = process.env.GATSBY_VISIT_EVENT_ENDPOINT;
const DAY_KEY_PREFIX = 'cv-visit-event-sent:';

function isBotUserAgent(): boolean {
  if (typeof navigator === 'undefined') return false;
  const ua = navigator.userAgent.toLowerCase();
  return /(bot|crawl|spider|slurp|lighthouse|headless)/i.test(ua);
}

function getTodayStorageKey(): string {
  const date = new Date().toISOString().slice(0, 10);
  return `${DAY_KEY_PREFIX}${date}`;
}

export function useVisitCounter(): void {
  console.log('VISIT_ENDPOINT=', VISIT_ENDPOINT);
  useEffect(() => {
    if (typeof window === 'undefined' || !VISIT_ENDPOINT) return;
    if (isBotUserAgent()) return;

    const storageKey = getTodayStorageKey();

    try {
      if (window.localStorage.getItem(storageKey) === '1') {
        return;
      }
    } catch {
      // Continue without dedupe when storage is unavailable.
    }

    void fetch(VISIT_ENDPOINT, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({
        page: window.location.pathname,
        referrer: document.referrer || null,
        lang: navigator.language,
        tz: Intl.DateTimeFormat().resolvedOptions().timeZone || null,
      }),
      cache: 'no-store',
      keepalive: true,
    })
      .then((res) => {
        if (!res.ok) {
          throw new Error(`visit-event failed: ${res.status}`);
        }

        try {
          window.localStorage.setItem(storageKey, '1');
        } catch {
          // noop if storage is unavailable
        }
      })
      .catch(() => {
        // Allow retry on a later page load if request fails.
        try {
          window.localStorage.removeItem(storageKey);
        } catch {
          // noop if storage is unavailable
        }
      });
  }, []);
}
